abled=false;convert.textContent='Convert to JPG'},'image/jpeg',Number(quality.value)/100)};img.onerror=()=>{err('Unable to read the PNG image.');convert.disabled=false;convert.textContent='Convert to JPG'};img.src=URL.createObjectURL(file)};download.onclick=()=>{if(!jpgBlob)return;const a=document.createElement('a');a.href=URL.createObjectURL(jpgBlob);a.download=(file.name||'image').replace(/\.png$/i,'')+'.jpg';a.click()};reset.onclick=()=>{input.value='';file=null;jpgBlob=null;fileInfo.textContent='No image selected';options.style.display='none';result.style.display='none';download.disabled=true;convert.disabled=true;convert.textContent='Convert to JPG';clearErr()};
